insert into activities (id, name, duration_minutes, is_active, sort_order, slug, summary, description_long, hero_image, gallery, show_on_website, seo_title, seo_description, min_age, restrictions, activity_type) values ('a1000000-0000-4000-8000-000000000001', 'Undersea walk', 45, true, 10, 'undersea-walk', 'Walk the lagoon floor in a helmet fed with air from the surface. No swimming needed.', 'You step down a ladder from our platform and walk along the sandy floor of the lagoon, about three to four metres down, wearing a helmet that is fed fresh air from the surface. Your head stays dry, glasses can stay on, and you breathe normally.
insert into activities (id, name, duration_minutes, is_active, sort_order, slug, summary, description_long, hero_image, gallery, show_on_website, seo_title, seo_description, min_age, restrictions, activity_type) values ('a1000000-0000-4000-8000-000000000002', 'Parasailing', 30, true, 20, 'parasailing', 'Ten minutes in the air above the lagoon, launched and landed from the back of the boat.', 'You take off from the deck of our winch boat and rise to around 60 metres above the lagoon. From up there you can see the colour of the reef change from turquoise to deep blue where it drops away.
insert into activities (id, name, duration_minutes, is_active, sort_order, slug, summary, description_long, hero_image, gallery, show_on_website, seo_title, seo_description, min_age, restrictions, activity_type) values ('a1000000-0000-4000-8000-000000000003', 'Snorkelling trip', 90, true, 30, 'snorkelling', 'A guided snorkel on the outer lagoon reef, with masks, fins and life jackets provided.', 'We take you by boat to a stretch of reef chosen for the day''s conditions and stay with you in the water. Beginners get a quick lesson on the boat first; confident swimmers can explore further with the guide.
insert into activities (id, name, duration_minutes, is_active, sort_order, slug, summary, description_long, hero_image, gallery, show_on_website, seo_title, seo_description, min_age, restrictions, activity_type) values ('a1000000-0000-4000-8000-000000000004', 'Glass-bottom boat', 60, true, 40, 'glass-bottom-boat', 'See the coral gardens through the hull without getting wet. Good for every age.', 'An hour over the shallow coral gardens in a boat with a glass viewing floor. The skipper stops over the best patches and names what you are looking at.
insert into activities (id, name, duration_minutes, is_active, sort_order, slug, summary, description_long, hero_image, gallery, show_on_website, seo_title, seo_description, min_age, restrictions, activity_type) values ('a1000000-0000-4000-8000-000000000005', 'Dolphin watching', 150, true, 50, 'dolphin-watching', 'An early start along the west coast to find spinner and bottlenose dolphins in the bay.', 'We leave at 07:00, when the dolphins are resting in the calm water of the west-coast bays. The skipper keeps to the national code of conduct: we approach slowly from the side, never chase, and leave when the pod moves on.
insert into activities (id, name, duration_minutes, is_active, sort_order, slug, summary, description_long, hero_image, gallery, show_on_website, seo_title, seo_description, min_age, restrictions, activity_type) values ('a1000000-0000-4000-8000-000000000006', 'Speed boat island run', 120, true, 60, 'speed-boat-island-run', 'A fast crossing to a small lagoon island, with time ashore to swim and walk the beach.', 'A quick, dry ride across the lagoon to one of the small islands off the coast, with an hour ashore to swim, walk the sandbank and find some shade under the filao trees.
insert into activities (id, name, duration_minutes, is_active, sort_order, slug, summary, description_long, hero_image, gallery, show_on_website, seo_title, seo_description, min_age, restrictions, activity_type) values ('a1000000-0000-4000-8000-000000000007', 'Sunset cruise', 120, true, 70, 'sunset-cruise', 'Two slow hours on the catamaran as the sun goes down, with drinks and canapés on board.', 'We leave about two hours before sunset and sail along the coast while the light goes gold, then turn for home as the sun drops behind the horizon.
insert into activities (id, name, duration_minutes, is_active, sort_order, slug, summary, description_long, hero_image, gallery, show_on_website, seo_title, seo_description, min_age, restrictions, activity_type) values ('a1000000-0000-4000-8000-000000000008', 'Turtle snorkel', 120, true, 80, 'turtle-snorkel', 'Snorkel the seagrass beds where green turtles come to feed, with a guide in the water.', 'Green turtles graze on the seagrass beds just inside the reef. We anchor well away from them and swim over quietly with a guide, keeping at least two metres away and never touching.
insert into activities (id, name, duration_minutes, slug, show_on_website) values ('a1000000-0000-4000-8000-0000000000ff', 'Unpublished test activity', 30, 'unpublished-test', false);
insert into packages (id, name, is_active, sort_order, slug, summary, description_long, hero_image, gallery, show_on_website, seo_title, seo_description, departs, returns) values ('b2000000-0000-4000-8000-000000000001', 'Full day catamaran', true, 10, 'full-day-catamaran', 'Catamaran, island visit, barbecue lunch and snorkelling. Departs 09:00, returns 15:30.', 'The day most of our guests remember. We sail out across the lagoon in the morning, stop to snorkel on the reef, then anchor off the island for a long lunch.
