insert into package_activities (package_id, activity_id, position) values ('b2000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000006', 1);
insert into packages (id, name, is_active, sort_order, slug, summary, description_long, hero_image, gallery, show_on_website, seo_title, seo_description, departs, returns) values ('b2000000-0000-4000-8000-000000000002', 'Dolphins and Crystal Rock', true, 20, 'dolphins-and-crystal-rock', 'Dolphins at dawn, a swim at Crystal Rock and lunch on Île aux Bénitiers. Back by 13:30.', 'An early morning on the southwest coast, under the shadow of Le Morne. We look for dolphins first, while the sea is calm, then run down the lagoon to Crystal Rock, the coral outcrop that stands on its own in the shallows.
