insert into resources (id, name, kind, capacity, is_active, sort_order, slug, summary, description_long, hero_image, gallery, show_on_website, seo_title, seo_description, length_m, specs, charter_terms) values ('c3000000-0000-4000-8000-000000000001', 'Catamaran 1', 'vessel', 30, true, 10, 'catamaran-1', '14 m sailing catamaran. Up to 30 guests, trampolines forward, shaded aft deck.', 'Our first sailing catamaran and still the one guests ask for by name. Two wide trampolines at the bow for lying in the sun, a shaded aft deck for lunch, and enough stability that nobody spills their drink.
